const orderedTopics=window.renderHubTopics(topics,(t, starterPlot)=>`<a class="topic-card ${t.id==='svm'?'featured':''}" href="${t.href}"><div class="topic-art art-${t.id}"><div class="art-top"><span>${t.label}</span><span class="status"><i></i>Готово</span></div><svg viewBox="0 0 320 180" aria-hidden="true">${starterPlot || plots[t.id]}</svg></div><div class="topic-body"><div class="topic-subtitle">${t.english}</div><div class="topic-title"><h4 class="${['logistic','imbalanced','linear','evaluation','neural'].includes(t.id)?'long-title':''}">${t.name}</h4><span class="round-arrow">↗</span></div><p>${t.desc}</p><div class="tags">${t.tags.map(s=>`<span>${s}</span>`).join('')}</div><div class="topic-foot">${t.lab}<span>Открыть урок →</span></div></div></a>`);
function photoBlock(p,large=false){const image=p.photo?`<img src="${esc(p.photo)}" alt="${esc(p.photoAlt||p.fullName)}">`:`<span class="portrait-initials" aria-hidden="true">${esc(p.initials)}</span><span class="photo-pending">Фото будет добавлено</span>`;return `<div class="portrait ${p.theme}${large?' portrait-large':''}">${image}${p.photoCaption?`<span class="avatar-caption">${esc(p.photoCaption)}</span>`:''}<span class="portrait-orbit" aria-hidden="true"></span></div>`;}
function renderCards(){document.getElementById('studentCards').innerHTML=Object.entries(profiles).map(([id,p],i)=>`<a class="student-card" href="#profile/${id}" aria-label="Открыть профиль: ${esc(p.fullName)}"><div class="student-number">0${i+1} / СТУДЕНТ</div>${photoBlock(p)}<div class="student-info"><div><h2>${esc(p.name)}</h2><p>${esc(p.role)}</p></div><span class="student-arrow" aria-hidden="true">↗</span></div><div class="student-meta"><span>${p.group?esc(p.group):'Группа будет добавлена'}</span><span>${p.gpa?'GPA '+esc(p.gpa):'GPA —'}</span></div></a>`).join('');}
function fact(label,value){return `<div class="fact"><dt>${label}</dt><dd${value?'':' class="pending"'}>${value?esc(value):'Будет добавлено'}</dd></div>`;}
function renderProfile(id){const p=profiles[id];if(!p)return false;
document.getElementById('profileContent').innerHTML=`<div class="profile-hero">${photoBlock(p,true)}<div class="profile-intro"><div class="eyebrow">ML LAB / ПРОФИЛЬ СТУДЕНТА</div><h1 id="profileTitle" tabindex="-1">${esc(p.fullName)}</h1><p class="profile-role">${esc(p.role)}</p><div class="profile-pills"><span>Машинное обучение</span><span>${esc(p.sections)}</span></div><p class="profile-about">${esc(p.about)}</p></div><div class="gpa-card"><span>GPA</span><strong>${p.gpa?esc(p.gpa):'—'}</strong><p>${p.gpa?'Средний академический балл':'Данные будут добавлены'}</p><div class="gpa-track" aria-hidden="true"><span style="width:${p.gpa?Math.min(100,Number(p.gpa)/4*100):0}%"></span></div></div></div>${p.photoCaption?`<p class="photo-credit">Фото аватара: <a href="https://commons.wikimedia.org/wiki/File:Brad_Pitt_2019_by_Glenn_Francis.jpg">© Glenn Francis, www.PacificProDigital.com</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. Исходный файл не изменён.</p>`:''}<div class="profile-columns"><section class="profile-panel" aria-labelledby="infoTitle"><div class="panel-heading"><span class="panel-index">01</span><h2 id="infoTitle">Учебные данные</h2></div><dl class="facts">${fact('ФИО',p.fullName===p.name?null:p.fullName)}${fact('Университет',p.university)}${fact('Образовательная программа',p.program)}${fact('Курс',p.course)}${fact('Группа',p.group)}${fact('Проект','ML LAB · Машинное обучение')}</dl></section><section class="profile-panel" aria-labelledby="contactsTitle"><div class="panel-heading"><span class="panel-index">02</span><h2 id="contactsTitle">Контакты</h2></div><div class="contacts">${p.contacts.map((c,i)=>c.href?`<a class="contact-row" href="${esc(c.href)}"><span class="contact-icon">${['↗','@','✉','↗'][i]}</span><span><small>${esc(c.label)}</small><b>${esc(c.text)}</b></span><span class="contact-arrow">↗</span></a>`:`<div class="contact-row contact-pending"><span class="contact-icon">${['↗','✉','@','+'][i]}</span><span><small>${esc(c.label)}</small><b>Будет добавлено</b></span><span class="contact-arrow">—</span></div>`).join('')}</div></section></div><section class="profile-lessons"><div class="section-heading"><div><div class="eyebrow">НАШИ СОВМЕСТНЫЕ РАБОТЫ</div><h2>Учебные <em>темы.</em></h2></div></div><div class="lesson-links">${orderedTopics.map(t=>`<a href="${t.id==='svm'?'svm.ru.html#'+(id==='akylbek'?1:4):t.href}"><span>${t.num}</span><div><b>${t.id==='logistic'?'Logistic Regression':t.name}</b><small>${t.id==='svm'?esc(p.sections)+' · '+esc(p.role):t.lab}</small></div><i>${t.external?'↗':'→'}</i></a>`).join('')}</div></section>`;document.title=p.fullName+' · ML LAB';return true;}
function route(focus=false){const hash=location.hash.slice(1),isProfile=hash.startsWith('profile/'),id=hash.split('/')[1];if(isProfile&&profiles&&renderProfile(id)){homeView.hidden=true;profileView.hidden=false;document.querySelectorAll('[data-nav]').forEach(a=>a.removeAttribute('aria-current'));window.scrollTo({top:0,behavior:'instant'});if(focus)document.getElementById('profileTitle').focus({preventScroll:true});}else{homeView.hidden=false;profileView.hidden=true;document.title='ML LAB — Машинное обучение · Акылбек & Алмас';const topic=/^topic-group-(?:[1-9]|1[01])$/.test(hash)?document.getElementById(hash):null;const section=topic?'topics':['home','team','topics','datasets'].includes(hash)?hash:'home';document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===section)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(section==='home')window.scrollTo({top:0,behavior:'instant'});else requestAnimationFrame(()=>{
  const target=topic||document.getElementById(section);
  if(topic){
    const headerHeight=document.querySelector('.header').offsetHeight;
    window.scrollTo({top:window.scrollY+topic.getBoundingClientRect().top-headerHeight-16,behavior:'instant'});
  }else{
    target.scrollIntoView({behavior:focus?'smooth':'instant',block:'start'});
  }
});}}
window.addEventListener('hashchange',()=>route(true));
fetch('profiles.ru.json').then(r=>{if(!r.ok)throw Error('profiles');return r.json();}).then(d=>{profiles=d;renderCards();route();}).catch(()=>{route();document.getElementById('studentCards').innerHTML='<div class="profile-error" role="alert">Профили не загрузились. <button type="button" id="retryProfiles">Обновить страницу</button></div>';document.getElementById('retryProfiles').onclick=()=>location.reload();});
